"""
MedBhasha Pydantic Schemas
Defines structured data contracts for medical extraction, verification, deterministic rule evaluation,
and vernacular language localization.
"""

from __future__ import annotations

from typing import List, Literal, Optional
from pydantic import BaseModel, Field


# ============================================================================
# 1. Raw Extracted Schemas (Generated by Gemini Structured Outputs)
# ============================================================================

class ExtractedMedicine(BaseModel):
    raw_name: str = Field(
        ...,
        description="Exact brand or generic name as written or visible on prescription",
    )
    dosage: str = Field(
        default="Unspecified",
        description="Dosage strength if visible (e.g., '500mg', '10mg', '5ml', 'Unspecified')",
    )
    frequency_code: str = Field(
        default="Unspecified",
        description="Frequency pattern as written (e.g., '1-0-1', '1-0-0', '0-0-1', 'BD', 'TDS', 'OD', 'SOS')",
    )
    morning_count: float = Field(
        default=0.0,
        description="Number of tablets/units to take in the morning",
    )
    afternoon_count: float = Field(
        default=0.0,
        description="Number of tablets/units to take in the afternoon/midday",
    )
    night_count: float = Field(
        default=0.0,
        description="Number of tablets/units to take at night/bedtime",
    )
    meal_timing: Literal["before_food", "after_food", "with_food", "unspecified"] = Field(
        default="unspecified",
        description="Instruction relative to meals (e.g., before food, after food, with food)",
    )
    duration_days: Optional[int] = Field(
        default=None,
        description="Course duration in days if stated (e.g., 5, 7, 30), or null if chronic/unspecified",
    )
    general_purpose: str = Field(
        default="Not specified",
        description="High-level clinical indication (e.g., 'Antibiotic for bacterial infection', 'Blood pressure management')",
    )


class ExtractedBiomarker(BaseModel):
    test_name: str = Field(
        ...,
        description="Name of the laboratory diagnostic test (e.g., 'HbA1c', 'Fasting Blood Sugar', 'Serum Creatinine')",
    )
    value: Optional[float] = Field(
        default=None,
        description="Extracted numeric measurement value (e.g., 7.2, 110, 1.1). Null if non-numeric/unclear.",
    )
    raw_value_text: str = Field(
        default="",
        description="Exact raw text for the value as printed on the lab report (e.g., '7.2%', '110 mg/dL', 'Negative')",
    )
    unit: str = Field(
        default="",
        description="Measurement unit (e.g., 'mg/dL', '%', 'g/dL', 'uIU/mL', 'cells/cumm')",
    )
    printed_reference_range: Optional[str] = Field(
        default=None,
        description="Biological reference interval printed on report (e.g., '4.0 - 5.6', '70 - 100'), if present",
    )


class DocumentExtraction(BaseModel):
    document_type: Literal["prescription", "lab_report", "mixed"] = Field(
        default="mixed",
        description="Primary classification of the uploaded medical document",
    )
    patient_instructions: List[str] = Field(
        default_factory=list,
        description="General doctor advice, dietary cautions, or follow-up instructions transcribed from document",
    )
    medicines: List[ExtractedMedicine] = Field(
        default_factory=list,
        description="List of all detected prescription medications",
    )
    biomarkers: List[ExtractedBiomarker] = Field(
        default_factory=list,
        description="List of all detected diagnostic laboratory tests and findings",
    )


# ============================================================================
# 2. Verified & Evaluated Schemas (Produced by Deterministic Verification)
# ============================================================================

class VerifiedMedicine(ExtractedMedicine):
    matched_name: Optional[str] = Field(
        default=None,
        description="Closest verified brand or generic match from national formulary database",
    )
    generic_composition: Optional[str] = Field(
        default=None,
        description="Pharmacological salt composition (e.g., 'Paracetamol 650mg')",
    )
    category: Optional[str] = Field(
        default=None,
        description="Therapeutic class (e.g., 'Analgesic / Antipyretic', 'Antidiabetic')",
    )
    confidence_score: float = Field(
        default=0.0,
        description="Fuzzy string matching confidence score between 0.0 and 100.0",
    )
    verification_status: Literal["verified", "low_confidence"] = Field(
        default="low_confidence",
        description="'verified' if confidence >= 80%, else 'low_confidence'",
    )
    warning: Optional[str] = Field(
        default=None,
        description="Safety warning flag if match confidence is below 80%",
    )


class EvaluatedBiomarker(ExtractedBiomarker):
    normalized_test_name: str = Field(
        ...,
        description="Standardized canonical test name resolved from aliases (e.g., 'HbA1c', 'Fasting Blood Sugar')",
    )
    standard_range: Optional[str] = Field(
        default=None,
        description="Standard clinical reference interval used for rule evaluation",
    )
    status: Literal["low", "normal", "high", "unverified_range"] = Field(
        default="unverified_range",
        description="Deterministic classification computed purely via numeric thresholds in Python",
    )
    interpretation: str = Field(
        default="",
        description="Objective clinical reading of the deterministic numeric range result",
    )


class DrugInteractionAlert(BaseModel):
    severity: Literal["danger", "warning", "info"] = Field(
        default="warning",
        description="Clinical severity of the alert ('danger', 'warning', or 'info')",
    )
    alert_type: Literal["drug_interaction", "duplicate_ingredient", "food_or_lifestyle", "clinical_caution"] = Field(
        default="drug_interaction",
        description="Classification of the safety alert",
    )
    medicines_involved: List[str] = Field(
        default_factory=list,
        description="List of medicines or chemical salts triggering this alert",
    )
    title: str = Field(
        ...,
        description="Short high-contrast headline for the safety alert",
    )
    description: str = Field(
        ...,
        description="Clinical rationale explaining why these substances interact or duplicate",
    )
    action_recommendation: str = Field(
        ...,
        description="Actionable recommendation for the patient to verify with pharmacist or doctor",
    )


class VerifiedDocumentResult(BaseModel):
    document_type: Literal["prescription", "lab_report", "mixed"]
    patient_instructions: List[str]
    medicines: List[VerifiedMedicine]
    biomarkers: List[EvaluatedBiomarker]
    total_medicines: int
    verified_medicines_count: int
    low_confidence_medicines_count: int
    flagged_biomarkers_count: int
    drug_interactions: List[DrugInteractionAlert] = Field(
        default_factory=list,
        description="Clinical safety alerts including dangerous drug-drug interactions and duplicate active ingredients",
    )


# ============================================================================
# 3. Vernacular Localization Schemas (Multi-language guidance & Audio TTS)
# ============================================================================

class LocalizedMedicineSchedule(BaseModel):
    medicine_name: str = Field(
        ...,
        description="Name of the medicine (verified match or raw name)",
    )
    schedule_text: str = Field(
        ...,
        description="Simple schedule instruction in target language (e.g. 'सुबह 1 गोली और रात को 1 गोली')",
    )
    food_instruction: str = Field(
        ...,
        description="Meal timing translated into patient's language (e.g. 'खाना खाने के बाद', 'After food')",
    )
    special_instructions: Optional[str] = Field(
        default=None,
        description="Crucial notes such as 'Do not stop abruptly' or 'Take with warm water'",
    )


class LocalizedBiomarkerExplanation(BaseModel):
    test_name: str = Field(
        ...,
        description="Name of the laboratory test",
    )
    value_summary: str = Field(
        ...,
        description="Plain summary of the measurement and standard range",
    )
    status_in_plain_language: str = Field(
        ...,
        description="Plain explanation of normal, high, or low in target vernacular language",
    )
    meaning_and_advice: str = Field(
        ...,
        description="What this reading means for the patient's daily health and questions for the doctor",
    )


class LocalizedGuidance(BaseModel):
    language: str = Field(
        ...,
        description="Two-letter language code: 'en', 'hi', 'or', 'bn', or 'ta'",
    )
    language_name: str = Field(
        ...,
        description="Full native name of the language (e.g. 'हिंदी', 'ଓଡ଼ିଆ', 'বাংলা', 'தமிழ்', 'English')",
    )
    spoken_summary_script: str = Field(
        ...,
        description="A concise 3-4 sentence spoken summary script in the target language written for natural audio TTS playback",
    )
    medicine_schedules: List[LocalizedMedicineSchedule] = Field(
        default_factory=list,
        description="Patient-friendly medication schedule cards",
    )
    biomarker_explanations: List[LocalizedBiomarkerExplanation] = Field(
        default_factory=list,
        description="Plain-language lab test explanations",
    )
    doctor_questions: List[str] = Field(
        default_factory=list,
        description="2-4 helpful questions for the patient to ask their doctor or pharmacist",
    )
    safety_disclaimer: str = Field(
        ...,
        description="Mandatory medical safety disclaimer in the target language reminding patient to consult doctor/pharmacist",
    )


class TTSRequest(BaseModel):
    text: str = Field(..., min_length=1, max_length=4000, description="Text to synthesize to speech")
    language: str = Field(default="hi", description="Language code: 'hi', 'bn', 'ta', 'or', or 'en'")
